const allocNs = 80;
const poolNs = 120;
const N = 1_000_000;
const freshTotal = allocNs * N;
const poolTotal = poolNs * N;
const delta = poolTotal - freshTotal;
console.log(`fresh alloc: ${(freshTotal/1e6).toFixed(1)} ms`);
console.log(`pooled:      ${(poolTotal/1e6).toFixed(1)} ms`);
console.log(delta > 0
  ? `pool is SLOWER by ${(delta/1e6).toFixed(1)} ms over ${N} ops -> REMOVE the pool`
  : `pool is FASTER by ${(-delta/1e6).toFixed(1)} ms -> keep it`);
